///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_Chk_form
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_Chk_form = async function () {
    const sbmOptions = {
        id: "tx_Chk_form",
        method: "post",
        action: "/stdcd/mfEtn.do?method=etnModifyProcess",
        ref: "dma_ChkFormReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldinf92500.tx_Chk_form" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


