 * @hidden N
*/
scwin.dataValidation = async function () {
    /* sdd-asis-lifecycle:begin dataValidation — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if ($c.str.getByteLength($c.util.getComponent('cal_isuDd').getValue()) == 0) {
        await $c.win.alert("발행일을 입력하세요.");
        $c.util.getComponent("cal_isuDd").focus();
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('cal_expDd').getValue()) == 0) {
        await $c.win.alert("만기일을 입력하세요.");
        $c.util.getComponent("cal_expDd").focus();
        return true;
    }
    if ($c.util.getComponent('cal_isuDd').getValue() > $c.util.getComponent('cal_expDd').getValue()) {
        await $c.win.alert("만기일은 발행일 이후로 입력하세요.");
        $c.util.getComponent("cal_isuDd").focus();
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_isuAmt').getValue()) == 0) {
        await $c.win.alert("발행금액 입력하세요.");
        $c.util.getComponent("ipt_isuAmt").focus();
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('slc_currTpCd').getValue()) == 0) {
        await $c.win.alert("발행통화 입력하세요.");
        document.curr_tp_cd.focus();
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_nusualIsuCondContn').getValue()) > 0) {
        if ($c.util.getComponent('ipt_nusualIsuCondContn').getValue().indexOf("\t") > -1 || $c.util.getComponent('ipt_nusualIsuCondContn').getValue().indexOf("\n") > -1 || $c.util.getComponent('ipt_nusualIsuCondContn').getValue().indexOf("\r") > -1) {
            await $c.win.alert("특이발행조건에 '탭문자' 혹은 '개행문자'가 포함되어있습니다.\n다시 입력해 주십시오.");
            $("#ipt_nusualIsuCondContn").select();
            return true;
        }
    }
    if (!$('input[name=group]').is(":checked")) {
        await $c.win.alert("'그룹'을 선택하세요.");
        console.error("[sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_focus — {target}.focus({args}) */
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('slc_attr01').getValue()) == 0) {
        await $c.win.alert("'1차속성'을 선택하세요.");
        $c.util.getComponent("slc_attr01").focus();
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('slc_attr02').getValue()) == 0) {
        await $c.win.alert("'2차속성'을 선택하세요.");
        $c.util.getComponent("slc_attr02").focus();
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('slc_attr03').getValue()) == 0) {
        await $c.win.alert("'3차속성'을 선택하세요.");
        $c.util.getComponent("slc_attr03").focus();
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('slc_attr04').getValue()) == 0) {
        await $c.win.alert("'4차속성'을 선택하세요.");
        $c.util.getComponent("slc_attr04").focus();
        return true;
    }
    if (!await scwin.dataLenCheck()) {
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_applComNm').getValue()) == 0) {
        await $c.win.alert("소속기관을 입력하세요.");
        $c.util.getComponent("ipt_applComNm").focus();
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_apctNm').getValue()) == 0) {
        await $c.win.alert("이름을 입력하세요.");
        $c.util.getComponent("ipt_apctNm").focus();
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_apctNm').getValue()) > 20) {
        await $c.win.alert("신청인 이름을 한글 10자, 영문 20자이내로 입력해 주세요");
        $c.util.getComponent("ipt_apctNm").focus();
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_ph01').getValue()) == 0) {
        await $c.win.alert("전화번호를 입력하세요.");
        $c.util.getComponent("ipt_ph01").focus();
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_ph02').getValue()) == 0) {
        await $c.win.alert("전화번호를 입력하세요.");
        $c.util.getComponent("ipt_ph02").focus();
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_ph03').getValue()) == 0) {
        await $c.win.alert("전화번호를 입력하세요.");
        $c.util.getComponent("ipt_ph03").focus();
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_fax01').getValue()) > 0 || $c.str.getByteLength($c.util.getComponent('ipt_fax02').getValue()) > 0 || $c.str.getByteLength($c.util.getComponent('ipt_fax03').getValue()) > 0) {
        if ($c.str.getByteLength($c.util.getComponent('ipt_fax01').getValue()) == 0) {
            await $c.win.alert("신청인 팩스번호를 입력하세요");
            $c.util.getComponent("ipt_fax01").focus();
            return true;
        }
        if ($c.str.getByteLength($c.util.getComponent('ipt_fax02').getValue()) == 0) {
            await $c.win.alert("신청인 팩스번호를 입력하세요");
            $c.util.getComponent("ipt_fax02").focus();
            return true;
        }
        if ($c.str.getByteLength($c.util.getComponent('ipt_fax03').getValue()) == 0) {
            await $c.win.alert("신청인 팩스번호를 입력하세요");
            $c.util.getComponent("ipt_fax03").focus();
            return true;
        }
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_email01').getValue()) == 0) {
        await $c.win.alert("이메일을 입력하세요");
        $c.util.getComponent("ipt_email01").focus();
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_email02').getValue()) == 0) {
        await $c.win.alert("이메일을 입력하세요");
        $c.util.getComponent("ipt_email02").focus();
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_email01').getValue() + "" + $c.util.getComponent('ipt_email02').getValue()) > 40) {
        await $c.win.alert("신청인 이메일을 한글 20자, 영문 40자이내로 입력하세요");
        $c.util.getComponent("ipt_email01").focus();
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_encrypCellphoneNo1').getValue()) == 0) {
        await $c.win.alert("신청인 휴대전화번호를 입력하세요");
        $c.util.getComponent("ipt_encrypCellphoneNo1").focus();
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_encrypCellphoneNo2').getValue()) == 0) {
